\begin{aligned}
\mathsf{Faithful}(\eta)&\Longleftrightarrow
\left[\forall h\in\operatorname{dom}(\eta_F)\ \forall\vec n\in\omega^{a_\eta(h)}\ \forall m\in\omega\right.\\
&\quad\left.\left(\mathbb N\models\mathsf{App}(\eta_F(h);\overline{\vec n}\frown\langle\bar m\rangle)
\Longleftrightarrow I_\eta^F(h)(\vec n)=m\right)\right]\\
&\quad\land\left[\forall R\in\operatorname{dom}(\eta_R)\ \forall\vec n\in\omega^{a_\eta(R)}
\left(\mathbb N\models\mathsf{App}(\eta_R(R);\overline{\vec n})
\Longleftrightarrow\vec n\in I_\eta^R(R)\right)\right].
\end{aligned}
